     3→import com.integration.security.ApiKeyAuthFilter;
     4→import org.springframework.context.annotation.Bean;
     5→import org.springframework.context.annotation.Configuration;
     6→import org.springframework.security.config.annotation.web.builders.HttpSecurity;
     7→import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
     8→import org.springframework.security.config.http.SessionCreationPolicy;
     9→import org.springframework.security.web.SecurityFilterChain;
    10→import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
    11→
    12→@Configuration
    13→@EnableWebSecurity
    14→public class SecurityConfig {
    15→
    16→    private final ApiKeyAuthFilter apiKeyAuthFilter;
    17→
    18→    public SecurityConfig(ApiKeyAuthFilter apiKeyAuthFilter) {
    19→        this.apiKeyAuthFilter = apiKeyAuthFilter;
    20→    }
    21→
    22→    @Bean
    23→    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
    24→        http
    25→            .csrf().disable()
    26→            .formLogin().disable()
    27→            .httpBasic().disable()
    28→            .sessionManagement().sessionCreationPolicy(SessionCreationPolicy.STATELESS)
    29→            .and()
    30→            .authorizeRequests()
    31→                .antMatchers("/webhook/**").permitAll()
    32→                .anyRequest().authenticated()
    33→            .and()
    34→            .addFilterBefore(apiKeyAuthFilter, UsernamePasswordAuthenticationFilter.class);
    35→        return http.build();
    36→    }
    37→}
